import{_ as a,o as t,c as o,ap as i}from"./chunks/framework.Dv1_Li4I.js";const h=JSON.parse('{"title":"Statistical model ownership","description":"","frontmatter":{},"headers":[],"relativePath":"rkppl-smooths.md","filePath":"rkppl-smooths.md","lastUpdated":null}'),s={name:"rkppl-smooths.md"};function r(n,e,d,l,p,c){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="Statistical-model-ownership" tabindex="-1">Statistical model ownership <a class="header-anchor" href="#Statistical-model-ownership" aria-label="Permalink to &quot;Statistical model ownership {#Statistical-model-ownership}&quot;">​</a></h1><p>BayesianRegressionModels owns spline, HSGP, GP and varying-effect statistical preparation and model bodies for both backends. RK-PPL compiles ordinary model statements and does not ship a statistical model catalogue.</p><p>Obtain a BRM-owned body with <code>BayesianRegressionModels.rkppl_model</code>, bind it in the defining module, or pass prepared data matrices to a hand-authored model. Explicit coefficient priors, matrix products, truncated distributions, array indexing and function calls retain their authored Julia semantics. The <a href="./rkppl">RK-PPL guide</a> describes these general language capabilities.</p><p>Model-specific bases, spectral weights, defaults and scientific acceptance belong with the BRM implementation. PK-specific models and helpers belong to downstream RKPPLBench.</p><p>Import preparation helpers from <code>BayesianRegressionModels.StatisticalPreparation</code> into the model module. The compiler no longer carries spline, HSGP, monotonic, DAR or varying-effect model IR. Varying effects are ordinary declared arrays and level gathers, or a BRM-owned <code>rkppl_model</code> body.</p>',5)])])}const f=a(s,[["render",r]]);export{h as __pageData,f as default};
